<?php

namespace Tests\Support;

use Database\Seeders\Support\NfeXmlBuilder;
use RuntimeException;
use ZipArchive;

/**
 * The Fiscal tests' hostile files (rnc-2 F6a, F6b; plan AM3). A valid document comes from
 * `NfeXmlBuilder` (the seeder's builder — F6b moved F6a's hand-written XMLs onto it); what is left
 * here is what no seed should ever build: a broken key, entity attacks and ZIP archives, every one
 * generated by the test that uses it.
 */
final class NfeFixture
{
    /** The same key with its check digit changed. */
    public static function brokenKey(string $key): string
    {
        $digit = ((int) substr($key, -1) + 1) % 10;

        return substr($key, 0, 43).$digit;
    }

    /**
     * A document whose recipient name is an external entity pointing at `$target`
     * (`file:///etc/hostname` in plan AM3).
     */
    public static function withExternalEntity(string $target): string
    {
        $document = str_replace('Destinatario exemplo Ltda', '&leak;', NfeXmlBuilder::nfe());

        return str_replace(
            '<?xml version="1.0" encoding="UTF-8"?>',
            '<?xml version="1.0" encoding="UTF-8"?><!DOCTYPE nfeProc [<!ENTITY leak SYSTEM "'.$target.'">]>',
            $document,
        );
    }

    /** The billion-laughs document: ten levels of ten references each. */
    public static function billionLaughs(): string
    {
        $entities = '<!ENTITY lol0 "lol">';

        for ($level = 1; $level <= 9; $level++) {
            $previous = '&lol'.($level - 1).';';
            $entities .= '<!ENTITY lol'.$level.' "'.str_repeat($previous, 10).'">';
        }

        $document = str_replace('Destinatario exemplo Ltda', '&lol9;', NfeXmlBuilder::nfe());

        return str_replace(
            '<?xml version="1.0" encoding="UTF-8"?>',
            '<?xml version="1.0" encoding="UTF-8"?><!DOCTYPE nfeProc ['.$entities.']>',
            $document,
        );
    }

    /**
     * The bytes of a ZIP holding `$entries` (entry name → content; a name ending in `/` is a
     * directory), each entry deflated.
     *
     * @param  array<string, string>  $entries
     */
    public static function zip(array $entries): string
    {
        $path = tempnam(sys_get_temp_dir(), 'nfe-zip');
        $zip = new ZipArchive;

        if ($path === false || $zip->open($path, ZipArchive::OVERWRITE) !== true) {
            throw new RuntimeException('Could not build the test ZIP.');
        }

        foreach ($entries as $name => $content) {
            if (str_ends_with($name, '/')) {
                $zip->addEmptyDir(rtrim($name, '/'));

                continue;
            }

            $zip->addFromString($name, $content);
            $zip->setCompressionName($name, ZipArchive::CM_DEFLATE);
        }

        $zip->close();
        $bytes = (string) file_get_contents($path);
        unlink($path);

        return $bytes;
    }

    /**
     * A ZIP whose one entry `$name` holds `$content` but whose headers claim `$claimedSize` bytes
     * uncompressed — the forged size `statIndex` would believe (plan AM3).
     */
    public static function zipWithForgedSize(string $name, string $content, int $claimedSize): string
    {
        $bytes = self::zip([$name => $content]);
        $actual = pack('V', strlen($content));
        $claimed = pack('V', $claimedSize);

        // The local header holds the size at offset 22, the central directory entry at offset 24.
        $local = strpos($bytes, "PK\x03\x04");
        $central = strpos($bytes, "PK\x01\x02");

        if ($local === false || $central === false || substr($bytes, $local + 22, 4) !== $actual || substr($bytes, $central + 24, 4) !== $actual) {
            throw new RuntimeException('Unexpected ZIP layout for the forged-size fixture.');
        }

        return substr_replace(substr_replace($bytes, $claimed, $central + 24, 4), $claimed, $local + 22, 4);
    }
}
